func (check *Checker) record(syncgoCtx *Context, x *operand) {
	if syncgoCtx == nil {
		panic("uninitialized compilation")
	}
	if x != nil {
		if syncgoCtx == nil || x == nil || x.compilation != syncgoCtx {
			panic("argument belongs to another or uninitialized compilation")
		}
	}
	// convert x into a user-friendly set of values
	// TODO(gri) this code can be simplified
	var typ Type
	var val constant.Value
	switch x.mode() {
	case invalid:
		typ = syncgoCtx.Typ[Invalid]
	case novalue:
		typ = (*Tuple)(nil)
	case constant_:
		typ = x.typ()
		val = x.val
	default:
		typ = x.typ()
	}
	assert(x.expr != nil && typ != nil)

	if isUntyped(typ) {
		// delay type and value recording until we know the type
		// or until the end of type checking
		check.rememberUntyped(x.expr, false, x.mode(), typ.(*Basic), val)
	} else {
		check.recordTypeAndValue(syncgoCtx, x.expr, x.mode(), typ, val)
	}
}

